// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type FlowchartAnimationProps = Record<string, any>;

const FlowchartAnimation: React.FC<FlowchartAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  durationInSeconds = 8,
  userLabel = "DRI",
  decisionPoints = ["Scope", "Priority", "Speed vs Quality"],
  taxMeterLabel = "Tax",
  taxMeterColor = "#ff3333",
  nodeColor = "#1a1a1a",
  lineColor = "#444444",
  padlockColor = "#ffaa00",
  textColor = "#ffffff",
  meterGlowIntensity = 0.6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Layout Calculations
  const startX = width * 0.15;
  const endX = width * 0.75;
  const startY = height * 0.5;
  const spacing = (endX - startX) / Math.max(1, decisionPoints.length);
  const meterRightEdge = width * 0.08;

  // Global Timings
  const introDuration = 30;
  const sequenceDuration = Math.max(30, fps * durationInSeconds - 60);
  const framesPerNode = sequenceDuration / Math.max(1, decisionPoints.length);
  const lineDrawDuration = Math.max(1, framesPerNode * 0.4);

  // Global Animations
  const startScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, stiffness: 120 },
  });

  const meterOpacity = interpolate(frame, [15, 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate Node States
  const nodes = decisionPoints.map((label, i) => {
    // Determine the start point of the line. For the first node, it's the edge of the DRI circle (radius 50).
    const prevX = i === 0 ? startX + 50 : startX + i * spacing;
    const currentX = startX + (i + 1) * spacing;

    const nodeStartFrame = introDuration + i * framesPerNode;
    const padlockPopFrame = nodeStartFrame + lineDrawDuration;

    const lineProgress = interpolate(
      frame,
      [nodeStartFrame, nodeStartFrame + lineDrawDuration],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    const padlockScale = spring({
      frame: frame - padlockPopFrame,
      fps,
      config: { damping: 12, stiffness: 150 },
    });

    const labelOpacity = interpolate(
      frame,
      [padlockPopFrame, padlockPopFrame + 15],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    const meterAddition = interpolate(
      frame,
      [padlockPopFrame, padlockPopFrame + 15],
      [0, 1 / Math.max(1, decisionPoints.length)],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );

    return {
      label,
      prevX,
      currentX,
      lineProgress,
      padlockScale,
      labelOpacity,
      meterAddition,
    };
  });

  const totalMeterProgress = nodes.reduce((acc, node) => acc + node.meterAddition, 0);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, transition: "none" }}>
      
      {/* Background SVG Canvas for connecting lines */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, transition: "none" }}>
        {nodes.map((node, i) => {
          const currentLineLength = (node.currentX - node.prevX) * node.lineProgress;
          return (
            <line
              key={`line-${i}`}
              x1={node.prevX}
              y1={startY}
              x2={node.prevX + currentLineLength}
              y2={startY}
              stroke={lineColor}
              strokeWidth={6}
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>

      {/* Start Node (DRI) */}
      <div
        style={{
          position: "absolute",
          left: startX,
          top: startY,
          width: 100,
          height: 100,
          borderRadius: "50%",
          backgroundColor: nodeColor,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: textColor,
          fontWeight: 700,
          fontSize: 28,
          transform: `translate(-50%, -50%) scale(${startScale})`,
          transition: "none",
          border: `6px solid ${lineColor}`,
          boxShadow: `0 8px 32px rgba(0,0,0,0.4)`,
        }}
      >
        {userLabel}
      </div>

      {/* Decision Points (Padlocks & Labels) */}
      {nodes.map((node, i) => (
        <div key={`node-${i}`} style={{ transition: "none" }}>
          {/* Padlock Icon */}
          <div
            style={{
              position: "absolute",
              left: node.currentX,
              top: startY,
              transform: `translate(-50%, -50%) scale(${node.padlockScale})`,
              transition: "none",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              width: 80,
              height: 80,
              backgroundColor: nodeColor,
              borderRadius: "50%",
              border: `4px solid ${lineColor}`,
              boxShadow: `0 8px 24px rgba(0,0,0,0.5)`,
            }}
          >
            <svg
              width="40"
              height="40"
              viewBox="0 0 24 24"
              fill="none"
              stroke={padlockColor}
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{ transition: "none" }}
            >
              <rect x="4" y="11" width="16" height="10" rx="3" ry="3" fill={`${padlockColor}22`} />
              <path d="M7 11V7a5 5 0 0110 0v4" />
              <circle cx="12" cy="16" r="1.5" fill={padlockColor} />
            </svg>
          </div>

          {/* Node Label */}
          <div
            style={{
              position: "absolute",
              left: node.currentX,
              top: startY + 70,
              transform: "translateX(-50%)",
              color: textColor,
              fontSize: 22,
              fontWeight: 500,
              opacity: node.labelOpacity,
              transition: "none",
              textAlign: "center",
              width: 260,
              letterSpacing: "0.02em",
            }}
          >
            {node.label}
          </div>
        </div>
      ))}

      {/* Tax Meter Container */}
      <div
        style={{
          position: "absolute",
          right: meterRightEdge,
          top: startY - 180,
          opacity: meterOpacity,
          transition: "none",
        }}
      >
        {/* Tax Meter Label */}
        <div
          style={{
            position: "absolute",
            top: -50,
            left: "50%",
            transform: "translateX(-50%)",
            color: textColor,
            fontSize: 26,
            fontWeight: 700,
            transition: "none",
            textAlign: "center",
            width: 150,
            letterSpacing: "0.05em",
            textTransform: "uppercase",
          }}
        >
          {taxMeterLabel}
        </div>

        {/* Tax Meter Bar */}
        <div
          style={{
            position: "relative",
            width: 70,
            height: 360,
            border: `6px solid ${lineColor}`,
            borderRadius: 40,
            padding: 6,
            backgroundColor: `${lineColor}33`,
            transition: "none",
            boxShadow: `0 16px 40px rgba(0,0,0,0.5)`,
          }}
        >
          {/* Inner Mask for Fill */}
          <div
            style={{
              position: "relative",
              width: "100%",
              height: "100%",
              borderRadius: 28,
              overflow: "hidden",
              transition: "none",
            }}
          >
            {/* The rising red fill */}
            <div
              style={{
                position: "absolute",
                bottom: 0,
                left: 0,
                right: 0,
                height: `${Math.max(0, Math.min(100, totalMeterProgress * 100))}%`,
                backgroundColor: taxMeterColor,
                boxShadow: `0 0 ${meterGlowIntensity * 50}px ${taxMeterColor}`,
                transition: "none",
              }}
            />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FlowchartAnimation;